-- --- archway ---

hl.bind("SUPER + space", hl.dsp.exec_cmd("rofi -show theme -modi 'theme:archway applet theme-selector'"))
hl.bind("SUPER + SHIFT + M", hl.dsp.exec_cmd("archway applet android-mount --rofi"))
hl.bind("SUPER + V", hl.dsp.exec_cmd("cliphist list | rofi -dmenu -display-columns 2 -p clipboard | cliphist decode | wl-copy"))
hl.bind("SUPER + SHIFT + S", hl.dsp.exec_cmd("archway applet screenshot region"))
hl.bind("Print", hl.dsp.exec_cmd("archway applet screenshot full"))
hl.bind("SUPER + P", hl.dsp.exec_cmd("rofi-rbw --type password --action copy"))

-- --- system ---

hl.bind("SUPER + SHIFT + Q", hl.dsp.exec_cmd("archway applet power --rofi"))
hl.bind("SUPER + Escape", hl.dsp.exec_cmd("hyprlock"))
hl.bind("SUPER + ALT + R", hl.dsp.reload_config())
hl.bind("SUPER + SHIFT + E", hl.dsp.exec_cmd("command -v uwsm >/dev/null 2>&1 && uwsm stop || hyprctl dispatch exit"))
hl.bind("SUPER + slash", hl.dsp.exec_cmd("kitty --class floating-term -e archway keys list"))

-- --- media ---

hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("pamixer -i 5 && notify-send -t 800 -h int:value:$(pamixer --get-volume) -h string:x-canonical-private-synchronous:volume volume $(pamixer --get-volume)%"), { repeating = true })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("pamixer -d 5 && notify-send -t 800 -h int:value:$(pamixer --get-volume) -h string:x-canonical-private-synchronous:volume volume $(pamixer --get-volume)%"), { repeating = true })
hl.bind("XF86AudioMute", hl.dsp.exec_cmd("pamixer -t && notify-send -t 800 -h string:x-canonical-private-synchronous:volume 'mute' $(pamixer --get-mute)"))
hl.bind("XF86AudioPlay", hl.dsp.exec_cmd("playerctl play-pause"))
hl.bind("XF86AudioNext", hl.dsp.exec_cmd("playerctl next"))
hl.bind("XF86AudioPrev", hl.dsp.exec_cmd("playerctl previous"))
hl.bind("XF86MonBrightnessUp", hl.dsp.exec_cmd("brightnessctl set +5%"), { repeating = true })
hl.bind("XF86MonBrightnessDown", hl.dsp.exec_cmd("brightnessctl set 5%-"), { repeating = true })

